import { expect, test } from "@playwright/test";

test.describe("Trail Runner 2 product page", () => {
  test.beforeEach(async ({ page }) => {
    await page.goto("/");
  });

  test("shows the Stride store, cart count, and main menu", async ({ page }) => {
    await expect(page.getByRole("link", { name: "Stride" })).toBeVisible();
    await expect(page.getByRole("link", { name: /cart/i })).toContainText(/\d+/);

    for (const section of ["Men", "Women", "Kids"]) {
      await expect(page.getByRole("link", { name: section, exact: true })).toBeVisible();
    }
  });

  test("shows a navigable path with links to earlier locations", async ({ page }) => {
    const breadcrumbs = page.getByRole("navigation", { name: /breadcrumb/i });

    await expect(breadcrumbs.getByRole("link", { name: "Shop", exact: true })).toBeVisible();
    await expect(breadcrumbs.getByRole("link", { name: "Trail", exact: true })).toBeVisible();
    await expect(breadcrumbs).toContainText("Trail Runner 2");
  });

  test("shows one shoe photo and cycles next and previous with wraparound", async ({ page }) => {
    const photo = page.getByRole("img", { name: /Trail Runner 2/i });
    const next = page.getByRole("button", { name: /next photo/i });
    const previous = page.getByRole("button", { name: /previous photo/i });

    await expect(photo).toBeVisible();
    const firstPhoto = await photo.getAttribute("src");

    await next.click();
    await expect(photo).not.toHaveAttribute("src", firstPhoto);

    await previous.click();
    await expect(photo).toHaveAttribute("src", firstPhoto);

    await previous.click();
    await expect(photo).not.toHaveAttribute("src", firstPhoto);
    await expect(page.getByText(/\d+\s*\/\s*\d+/)).toBeVisible();
  });

  test("shows the price and explains that it includes taxes", async ({ page }) => {
    await expect(page.getByText(/^\$\d+(?:\.\d{2})?$/)).toBeVisible();

    const priceInfo = page.getByRole("button", { name: /price information|includes taxes/i });
    await priceInfo.hover();
    await expect(page.getByRole("tooltip")).toContainText(/taxes included/i);
  });

  test("allows exactly one of blue, black, and grey to be selected", async ({ page }) => {
    const colors = ["Blue", "Black", "Grey"];

    for (const color of colors) {
      const swatch = page.getByRole("radio", { name: new RegExp(color, "i") });
      await expect(swatch).toBeVisible();
      await swatch.click();
      await expect(swatch).toBeChecked();
    }

    await expect(
      page.getByRole("radio", { checked: true }),
    ).toHaveCount(1);
  });

  test("opens a size picker, shows only the selected size, and excludes sold-out sizes", async ({
    page,
  }) => {
    const sizePicker = page.getByRole("button", { name: /size/i }).first();
    await expect(sizePicker).toContainText(/\d/);
    await sizePicker.click();

    const sizeList = page.getByRole("listbox", { name: /size/i });
    await expect(sizeList).toBeVisible();
    await expect(sizeList.getByRole("option", { name: /sold out/i })).toBeDisabled();

    const availableSize = sizeList
      .getByRole("option")
      .filter({ hasNotText: /sold out/i })
      .first();
    await availableSize.click();
    await expect(sizePicker).toContainText(await availableSize.textContent());
    await expect(sizeList).toBeHidden();
  });

  test("opens the size guide, calculates a size by foot length and unit, and must be closed", async ({
    page,
  }) => {
    await page.getByRole("button", { name: /size guide/i }).click();

    const guide = page.getByRole("dialog", { name: /size guide/i });
    await expect(guide).toBeVisible();
    await expect(guide.getByRole("table")).toBeVisible();

    await guide.getByLabel(/foot length/i).fill("26");
    await guide.getByRole("radio", { name: /EU/i }).check();
    await expect(guide.getByText(/size/i).last()).toBeVisible();

    await guide.getByRole("button", { name: /close/i }).click();
    await expect(guide).toBeHidden();
  });

  test("changes quantity by typing and by one-item controls", async ({ page }) => {
    const quantity = page.getByRole("spinbutton", { name: /quantity/i });
    await expect(quantity).toHaveValue("1");

    await page.getByRole("button", { name: /increase quantity|plus/i }).click();
    await expect(quantity).toHaveValue("2");
    await page.getByRole("button", { name: /decrease quantity|minus/i }).click();
    await expect(quantity).toHaveValue("1");

    await quantity.fill("3");
    await expect(quantity).toHaveValue("3");
  });

  test("requires a size before adding the shoe and confirms a successful add", async ({ page }) => {
    const addToCart = page.getByRole("button", { name: /add to cart/i });
    await addToCart.click();
    await expect(page.getByRole("alert")).toContainText(/choose|select.*size/i);

    await page.getByRole("button", { name: /size/i }).first().click();
    await page.getByRole("option", { name: /^\d/ }).filter({ hasNotText: /sold out/i }).first().click();
    await addToCart.click();
    await expect(page.getByRole("alert")).toContainText(/added.*cart|cart.*added/i);
  });

  test("toggles the shoe in and out of the wishlist", async ({ page }) => {
    const wishlist = page.getByRole("button", { name: /wishlist|favorite/i });

    await expect(wishlist).toHaveAttribute("aria-pressed", "false");
    await wishlist.click();
    await expect(wishlist).toHaveAttribute("aria-pressed", "true");
    await wishlist.click();
    await expect(wishlist).toHaveAttribute("aria-pressed", "false");
  });

  test("shows one of details, reviews, and shipping at a time", async ({ page }) => {
    const sections = ["Details", "Reviews", "Shipping"];

    await expect(page.getByRole("tabpanel")).toContainText(/./);
    for (const section of sections) {
      const tab = page.getByRole("tab", { name: section, exact: true });
      await tab.click();
      await expect(tab).toHaveAttribute("aria-selected", "true");
      await expect(page.getByRole("tabpanel")).toBeVisible();
    }

    await expect(page.getByRole("tab", { selected: true })).toHaveCount(1);
  });

  test("reveals an answer when a common question is opened", async ({ page }) => {
    const questions = page.getByRole("button", { name: /\?/ });
    await expect(questions).toHaveCount(await questions.count());
    await expect(questions.first()).toHaveAttribute("aria-expanded", "false");

    await questions.first().click();
    await expect(questions.first()).toHaveAttribute("aria-expanded", "true");
    await expect(page.getByRole("region").first()).toBeVisible();
  });

  test("shows customer help, company, and social links at the bottom", async ({ page }) => {
    const footer = page.getByRole("contentinfo");
    await footer.scrollIntoViewIfNeeded();

    await expect(footer).toContainText(/customer help/i);
    await expect(footer).toContainText(/company/i);
    await expect(footer.getByRole("link", { name: /instagram|facebook|twitter|x/i })).toBeVisible();
  });
});

